  justify-content: center;
  gap: 1rem;
  margin-top: 2rem;
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  border: 2px solid var(--gray-200);
  background: var(--white);
  cursor: pointer;
  font-size: 1.1rem;
  transition: all var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
}

.carousel-btn:hover { background: var(--black); color: var(--lime); border-color: var(--black); }

.carousel-dots { display: flex; gap: 0.5rem; }

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--gray-200);
  cursor: pointer;
  transition: all var(--transition);
  border: none;
