.pricing-card {
  background: var(--white);
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  position: relative;
  transition: all var(--transition);
}

.pricing-card:hover { box-shadow: var(--shadow-lg); transform: translateY(-3px); }

.pricing-card--featured {
  border-color: var(--black);
  box-shadow: var(--shadow-lg);
}

.pricing-badge {
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: var(--lime);
  color: var(--black);
  padding: 0.3rem 1rem;
  border-radius: 2rem;
  font-size: 0.75rem;
  font-weight: 800;
  white-space: nowrap;
}

.pricing-tier {
  font-size: 1rem;
  font-weight: 700;
  color: var(--gray-500);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.5rem;
}

.pricing-price {
  font-size: 2.25rem;
  font-weight: 800;
  color: var(--gray-900);
  letter-spacing: -0.025em;
}

.pricing-then {
  font-size: 0.8rem;
  color: var(--gray-400);
  margin-bottom: 1.5rem;
}

.pricing-features {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.6rem;
}

.pricing-features li {
  font-size: 0.875rem;
  color: var(--gray-700);
}

.pricing-note { color: var(--gray-400) !important; }

/* =================== INTEGRATIONS =================== */
.integrations-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.integration-item {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-md);
  padding: 0.65rem 1.25rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
  transition: all var(--transition);
  white-space: nowrap;
}

.integration-item:hover {
  border-color: var(--black);
  color: var(--black);
  background: var(--gray-50);
  transform: translateY(-1px);
}

