.footer-col ul { list-style: none; display: flex; flex-direction: column; gap: 0.6rem; }

.footer-col a {
  color: rgba(255,255,255,0.5);
  text-decoration: none;
  font-size: 0.875rem;
  transition: color var(--transition);
}

.footer-col a:hover { color: var(--white); }

.footer-bottom {
  padding-top: 2rem;
  font-size: 0.8rem;
  text-align: center;
}

