.feature-card {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all var(--transition);
}

.feature-card:hover { box-shadow: var(--shadow-md); border-color: var(--gray-300, #cbd5e1); transform: translateY(-2px); }

.feature-card-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
  display: block;
}

.feature-card h3 {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 0.5rem;
}

.feature-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.6;
}

/* =================== STEPS =================== */
.steps-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 2rem;
  position: relative;
}

.step-card {
  text-align: center;
  padding: 2.5rem 1.5rem;
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-xl);
  position: relative;
}

.step-number {
  width: 52px;
  height: 52px;
  background: var(--lime);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 1.25rem;
  font-weight: 800;
  color: var(--black);
  margin: 0 auto 1.25rem;
}

.step-card h3 {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--gray-900);
  margin-bottom: 0.75rem;
}

.step-card p {
  font-size: 0.875rem;
  color: var(--gray-500);
  line-height: 1.65;
}

/* =================== TOOLS GRID =================== */
.tools-section-grid {
  display: grid;
  grid-template-columns: repeat(5, 1fr);
  gap: 1.25rem;
}

.tools-category {
  background: var(--gray-50);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
}

.tools-category-label {
  display: inline-block;
  background: var(--black);
  color: var(--lime);
  padding: 0.2rem 0.6rem;
  border-radius: 0.4rem;
  font-size: 0.7rem;
  font-weight: 800;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 0.875rem;
}

.tools-category ul {
