  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all var(--transition);
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.resource-card:hover { box-shadow: var(--shadow-md); border-color: var(--black); transform: translateY(-2px); }

.resource-card-type {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--gray-400);
}

.resource-card h3 {
  font-size: 1rem;
  font-weight: 700;
  color: var(--gray-900);
  line-height: 1.4;
}

.resource-card p {
  font-size: 0.85rem;
  color: var(--gray-500);
  line-height: 1.6;
  flex: 1;
}

.resource-link {
  font-size: 0.85rem;
  font-weight: 700;
  color: var(--black);
}

/* =================== FILE TYPES =================== */
.file-types-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
  justify-content: center;
}

.file-type-chip {
  background: var(--white);
  border: 1.5px solid var(--gray-200);
  border-radius: var(--radius-sm);
  padding: 0.6rem 1.1rem;
  font-size: 0.875rem;
  font-weight: 600;
  color: var(--gray-700);
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

/* =================== SPOTLIGHT =================== */
.spotlight-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.spotlight-card {
  background: var(--gray-900);
  border-radius: var(--radius-xl);
  padding: 2rem;
  color: var(--white);
}

.spotlight-card h3 {
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--white);
  margin-bottom: 0.75rem;
}

.spotlight-card p {
  font-size: 0.875rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.65;
}

.spotlight-icon {
  font-size: 2rem;
  margin-bottom: 1rem;
}

/* =================== RESPONSIVE =================== */
@media (max-width: 1024px) {
  .tools-section-grid { grid-template-columns: repeat(3, 1fr); }
  .footer-links { grid-template-columns: repeat(2, 1fr); }
}

@media (max-width: 768px) {
  .nav-links { display: none; flex-direction: column; position: absolute; top: 68px; left: 0; right: 0; background: var(--white); padding: 1rem; border-bottom: 1px solid var(--gray-200); z-index: 99; }
  .nav-links.open { display: flex; }
  .nav-toggle { display: flex; }
  .nav-cta { display: none; }

  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .steps-grid { grid-template-columns: 1fr; }
  .tools-section-grid { grid-template-columns: repeat(2, 1fr); }
  .resources-grid { grid-template-columns: 1fr; }
  .spotlight-grid { grid-template-columns: 1fr; }
  .pricing-grid { grid-template-columns: 1fr; }
  .two-col-section { grid-template-columns: 1fr; }
  .footer-top { grid-template-columns: 1fr; gap: 2rem; }
  .footer-links { grid-template-columns: repeat(2, 1fr); }
  .stat-divider { display: none; }
  .stats-grid { gap: 1.5rem; }
  .testimonial-card { flex: 0 0 calc(100% - 0rem); }
}

@media (max-width: 540px) {
  .products-grid { grid-template-columns: 1fr; }
  .features-grid { grid-template-columns: 1fr; }
  .tools-section-grid { grid-template-columns: 1fr 1fr; }
  .footer-links { grid-template-columns: 1fr 1fr; }
  .hero-ctas { flex-direction: column; align-items: center; }
  .cta-banner-btns { flex-direction: column; align-items: center; }
}

/* =================== SCROLL ANIMATION =================== */
.fade-up {
  opacity: 0;
  transform: translateY(24px);
  transition: opacity 0.5s ease, transform 0.5s ease;
}

.fade-up.visible {
  opacity: 1;
  transform: translateY(0);
}

/* =================== MEMBERSHIP SPECIFIC =================== */
.membership-stat-highlight {
  background: linear-gradient(135deg, var(--black) 0%, #1a1a1a 100%);
  border-radius: var(--radius-xl);
  padding: 3rem;
  text-align: center;
  color: var(--white);
}

.membership-big-stat {
  font-size: clamp(3rem, 6vw, 5rem);
  font-weight: 800;
  color: var(--lime);
  letter-spacing: -0.04em;
  line-height: 1;
}

.membership-big-label {
  font-size: 1rem;
  color: rgba(255,255,255,0.7);
  margin-top: 0.5rem;
}

.pricing-membership-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1.5rem;
}

.membership-tier-card {
  border: 2px solid var(--gray-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all var(--transition);
}

.membership-tier-card:hover { border-color: var(--black); box-shadow: var(--shadow-md); }
.membership-tier-card--featured { border-color: var(--black); }

@media (max-width: 768px) {
  .pricing-membership-grid { grid-template-columns: 1fr; }
}

